export const MAX_IMAGE_UPLOAD_LIMIT = 10;
export const MAX_VIDEO_UPLOAD_LIMIT = 5;
export const MAX_VIDEO_FILE_SIZE = '100MB';
export const MAX_VIDEO_DURATION = 60;
export const MAX_PARALLEL_UPLOADS = 10;
export function isVideoUrl(url) {
    const pathname = url.split(/[?#]/, 1)[0];
    return /\.(mp4|webm|mov|avi|mkv)$/i.test(pathname);
}
export function splitMediaUrls(urls) {
    return urls.reduce((acc, url) => {
        if (!url)
            return acc;
        if (isVideoUrl(url)) {
            acc.videos.push(url);
        }
        else {
            acc.images.push(url);
        }
        return acc;
    }, { images: [], videos: [] });
}
export function getMediaUrlsByType(items) {
    return splitMediaUrls(items.map(item => item?.url || '').filter(Boolean));
}
export function parseMediaField(value) {
    if (!value)
        return [];
    if (Array.isArray(value))
        return value.filter(Boolean);
    return value
        .split(',')
        .map(url => url.trim())
        .filter(Boolean);
}
export function countMediaByType(items) {
    return items.reduce((counts, item) => {
        const url = item?.url || '';
        if (isVideoUrl(url)) {
            counts.video += 1;
        }
        else {
            counts.image += 1;
        }
        return counts;
    }, { image: 0, video: 0 });
}
export function createPreloadedMediaItem(url) {
    return { id: url, url };
}
export function removeUploadedImage(images, removedId) {
    const normalizedId = String(removedId);
    let removed = false;
    return images.filter(image => {
        const imageId = image?.id !== undefined && image?.id !== null ? String(image.id) : '';
        const imageUrl = String(image?.url ?? '');
        const matches = imageId === normalizedId || imageUrl === normalizedId;
        if (matches) {
            if (removed) {
                return true;
            }
            removed = true;
            return false;
        }
        return true;
    });
}
export function syncHiddenMediaInputs(imagesInput, videosInput, items) {
    const { images, videos } = getMediaUrlsByType(items);
    if (imagesInput)
        imagesInput.value = images.join(',');
    if (videosInput)
        videosInput.value = videos.join(',');
}
export function normalizeSubmittedMedia(data, allowAttachImages, allowAttachVideos) {
    if (!allowAttachImages) {
        delete data.images;
    }
    if (!allowAttachVideos) {
        delete data.videos;
    }
}
